/**
 * What a row, a button or a segmented does: ui.action with its id. An object, so later kinds of action (push or pop a
 * page) are fields added here.
 */
@Serializable
data class ExtensionAction(
    val id: String = "",
    /**
     * Ask the user first, in these words.
     */
    val confirm: String? = null,
    /**
     * Send the page's fields as values.
     */
    val submit: Boolean? = null,
)

@Serializable
data class ExtensionBadge(
    val text: String = "",
    val tone: String? = null,
)

@Serializable
data class ExtensionChoice(
    val value: String = "",
    val title: String? = null,
)

/**
 * One line, or one color of bars. No tone: the app's own colors, in order.
 */
@Serializable
data class ExtensionChartSeries(
    val name: String? = null,
    val tone: String? = null,
    val points: List<ExtensionChartPoint> = emptyList(),
)

/**
 * A value at a label (a day, a model); display is how to write it ("¥1.20"), else the app writes value with the unit.
 */
@Serializable
data class ExtensionChartPoint(
    val label: String = "",
    val value: Double = 0.0,
    val display: String? = null,
)

@Serializable
data class ExtensionStat(
    val label: String = "",
    val value: String = "",
    val detail: String? = null,
    val tone: String? = null,
)

/**
 * What ui.action answers: a new view, a short message, an https link to open, or nothing (draw again).
 */
@Serializable
data class ExtensionActionResult(
    val view: ExtensionView? = null,
    val toast: String? = null,
    @SerialName("open_url") val openUrl: String? = null,
)

/**
 * Values of PersonaCardKind.
 */
object ExtensionPersonaCardKind {
    const val STAT = "stat"
    const val STACKED_BAR = "stacked_bar"
    const val LINE = "line"
    const val BAR = "bar"
    val ALL = listOf("stat", "stacked_bar", "line", "bar")
}

/**
 * The assistant's ```persona-card block (#886): one JSON object. Joins the components in #1850; this form keeps
 * drawing.
 */
@Serializable
data class ExtensionPersonaCard(
    val type: String = "",
    val title: String? = null,
    val subtitle: String? = null,
    val value: Double? = null,
    val unit: String? = null,
    val note: String? = null,
    val total: ExtensionCardAmount? = null,
    val segments: List<ExtensionCardPart>? = null,
    val rest: ExtensionCardPart? = null,
    val points: List<ExtensionCardPart>? = null,
)

@Serializable
data class ExtensionCardAmount(
    val value: Double = 0.0,
    val unit: String? = null,
)

@Serializable
data class ExtensionCardPart(
    val label: String = "",
    val value: Double = 0.0,
    val note: String? = null,
)
